const SECURITY_HEADERS = {
  "x-content-type-options":"nosniff",
  "referrer-policy":"no-referrer",
  "x-frame-options":"DENY",
  "permissions-policy":"camera=(), microphone=(), geolocation=()",
  "content-security-policy":"default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data: blob:; font-src 'self' data:; connect-src 'self'; frame-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'",
  "cache-control":"no-store, max-age=0"
};
export default {
  async fetch(request) {
    if (request.method !== "GET" && request.method !== "HEAD") {
      return new Response(JSON.stringify({error:"Method not allowed."}), {
        status:405, headers:{"content-type":"application/json; charset=utf-8", ...SECURITY_HEADERS, allow:"GET, HEAD"}
      });
    }
    const url = new URL(request.url);
    const path = url.pathname === "" ? "/" : url.pathname;
    const content = FILES.get(path);
    if (content === undefined) return new Response("Not Found", {status:404,headers:SECURITY_HEADERS});
    const type = path.endsWith(".css") ? "text/css; charset=utf-8" :
      path.endsWith(".js") ? "text/javascript; charset=utf-8" : "text/html; charset=utf-8";
    return new Response(request.method === "HEAD" ? null : content, {
      status:200, headers:{"content-type":type, ...SECURITY_HEADERS}
    });
  }
};
